--
-- Table structure for table `employees`
--

DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employees` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` text NOT NULL,
  `employee_id` text DEFAULT NULL,
  `qatar_id` text DEFAULT NULL,
  `qatar_id_expiry` text DEFAULT NULL,
  `email` text DEFAULT NULL,
  `phone` text DEFAULT NULL,
  `address` text DEFAULT NULL,
  `position` text DEFAULT NULL,
  `department` text DEFAULT NULL,
  `hire_date` text DEFAULT NULL,
  `status` varchar(255) DEFAULT 'active',
  `emergency_contact` text DEFAULT NULL,
  `emergency_phone` text DEFAULT NULL,
  `bank_account` text DEFAULT NULL,
  `bank_name` text DEFAULT NULL,
  `monthly_salary` decimal(10,2) DEFAULT NULL,
  `per_day_rate` decimal(10,2) DEFAULT NULL,
  `per_hour_rate` decimal(10,2) DEFAULT NULL,
  `advances` decimal(10,2) DEFAULT NULL,
