INSERT INTO `followup_templates` VALUES (2,'Quotation Expiry Reminder','quotation','email','Reminder: Quotation #{quotation_id} expires soon','Dear {client_name},\r\n\r\nThis is a friendly reminder that your quotation #{quotation_id} for {project_name} will expire on {expiry_date}.\r\n\r\nTo avoid any delays and secure the current pricing, we encourage you to confirm your acceptance before the expiry date.\r\n\r\nIf you need an extension or have any questions, please let us know.\r\n\r\nBest regards,\r\n{company_name}',1,'2025-10-02 06:12:01','2025-10-02 06:12:01'),(3,'Invoice Payment Reminder (5 days before due)','invoice','email','Payment Reminder: Invoice #{invoice_id} due in 5 days','Dear {client_name},\r\n\r\nThis is a friendly reminder that payment for Invoice #{invoice_id} is due in 5 days ({due_date}).\r\n\r\nInvoice Details:\r\n- Invoice ID: #{invoice_id}\r\n- Amount: {total_amount}\r\n- Due Date: {due_date}\r\n- Outstanding Balance: {balance}\r\n\r\nPlease ensure payment is made by the due date to avoid any late fees.\r\n\r\nIf you have already made the payment, please disregard this message.\r\n\r\nBest regards,\r\n{company_name}',1,'2025-10-02 06:12:01','2025-10-02 06:12:01'),(4,'Invoice Overdue Notice','invoice','email','OVERDUE: Invoice #{invoice_id} - Immediate Payment Required','Dear {client_name},\r\n\r\nOur records show that Invoice #{invoice_id} is now overdue by {days_overdue} days.\r\n\r\nInvoice Details:\r\n- Invoice ID: #{invoice_id}\r\n- Amount: {total_amount}\r\n- Due Date: {due_date}\r\n- Outstanding Balance: {balance}\r\n\r\nPlease arrange for immediate payment to avoid any further action. If there are any issues preventing payment, please contact us immediately to discuss payment arrangements.\r\n\r\nBest regards,\r\n{company_name}',1,'2025-10-02 06:12:01','2025-10-02 06:12:01');
/*!40000 ALTER TABLE `followup_templates` ENABLE KEYS */;
UNLOCK TABLES;

