INSERT INTO `lpo_items` VALUES (2,2,'Scope of Work  Section 01 – Footing Beam Casting of reinforced concrete footing beam for 160 meters linear length Size: 20 × 20 cm  Section 02 – RCC Column Installation Supply and installation of 56 RCC columns Size: 20 × 20 cm  Section 03 – Block Masonry Work Block wall construction along 160-meter perimeter Height: 3 meters  Section 04 – Wall Finishing (Plastering) Cement plastering on both internal and external sides of the wall',1.00,'set',80000.00,80000.00,''),(3,3,'SINAGE',1.00,'set',1500.00,1500.00,''),(4,4,'Supply & Fabrication of Premium Wooden Box 150 385 57,750.00         Supply and fabrication of premium quality wooden box made from  high-grade MDF, finished with oak veneer wood for a refined  appearance. The box is designed with an internal velvet partition to ensure  organized and secure storage. Each unit will feature a brass logo mounted on the top surface,  enhancing the overall elegant and premium look. The box will be  manufactured in the size of 50 cm (W) x 30 cm (D) x 25 cm (H). The finishing will include high-quality painting, precision CNC  cutting, and detailed engraving to ensure superior durability, fine  craftsmanship, and aesthetic excellence.',150.00,'set',385.00,57750.00,''),(5,4,'Supply & Fabrication of Gift Item – Resin Quran Stand 150 180 27,000.00         Supply and fabrication of premium quality resin Quran stand,  crafted from high-grade resin material to ensure durability and a  superior finish. The stand will be designed with an elegant mosaic pattern using  advanced hydro dipping technology, providing a unique, artistic,  and decorative appearance suitable for gifting purposes. Each unit will be manufactured in the size of 50 cm (W) x 25 cm  (D) x 25 cm (H) and finished with a smooth, refined surface to  enhance both aesthetic appeal and functional usability.',150.00,'set',180.00,27000.00,'');
/*!40000 ALTER TABLE `lpo_items` ENABLE KEYS */;
UNLOCK TABLES;

